[MethodImpl(MethodImplOptions.NoInlining)]
static WeakReference RunPlugin(string path)
{
    var alc = new PluginLoadContext(path);
    Assembly asm = alc.LoadFromAssemblyPath(path);
    // ... create the plugin and call it ...
    alc.Unload();
    return new WeakReference(alc);
}

var weak = RunPlugin("/app/plugins/Report.dll");
for (int i = 0; weak.IsAlive && i < 10; i++)
{
    GC.Collect();
    GC.WaitForPendingFinalizers();
}
Console.WriteLine(weak.IsAlive ? "not unloaded" : "unloaded");

